import { useEffect, useRef, useState } from 'preact/hooks';

import styles from './styles.module.scss';
import { getUILanguage } from '../../../../../shared/chromeApi';
import { FunctionalComponent } from 'preact';

// eventually move that to i18n
const MESSAGES = {
  info_no_recognized: `Didn't get that.`,
  info_try_again: `Try again`,
  info_speak_now: 'Speak now.',
  info_listening: 'Listening...',
  info_no_speech: `No speech was detected. You may need to adjust your <a href="https://support.google.com/chrome/answer/2693767">microphone settings</a>. or`,
  info_no_microphone: `No microphone was found. Ensure that a microphone is installed and that <a href="https://support.google.com/chrome/answer/2693767">microphone settings</a> are configured correctly.`,
  info_allow: `Click the "Allow" button above to enable your microphone.`,
  info_denied: `Permission to use microphone was denied. To change, go to <a href="chrome://settings/content/microphone">chrome://settings/content/microphone</a>`,
  info_blocked: `Permission to use microphone is blocked. To change, go to <a href="chrome://settings/content/microphone">chrome://settings/content/microphone</a>`,
  info_upgrade: `Web Speech API is not supported by this browser. Upgrade to <a href="https://www.google.com/chrome">Chrome</a> version 25 or later.`,
};

const DEFAULT_REF = {
  text: '',
  recognition: null,
  ignoreOnend: false,
  startTimestamp: null,
};

interface Props {
  onClose: (text?: string) => unknown,
}

const VoiceSearch: FunctionalComponent<Props> = ({ onClose }: Props) => {
  const [text, setText] = useState('');
  const [message, setMessage] = useState(null);
  const [isRecognizing, setRecognizing] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);

  const ref = useRef({ ...DEFAULT_REF });

  const handleSetText = (v = '') => {
    let parsedText = v.trim();
    parsedText = parsedText.endsWith('.')
      ? parsedText.slice(0, -1)
      : parsedText;
    ref.current.text = parsedText;
    setText(parsedText);
  };

  const handleClose = (result?: string) => {
    ref.current.recognition.stop();
    onClose(result);
  };

  const tryAgain = () => {
    if (isRecognizing) {
      ref.current.recognition.stop();
      return;
    }

    handleSetText('');
    ref.current.ignoreOnend = false;
    ref.current.startTimestamp = Date.now();
    ref.current.recognition.start();
  };

  useEffect(() => {
    if (!('webkitSpeechRecognition' in window)) {
      setMessage('info_upgrade');
      return;
    }

    let finalTranscript = '';

    const recognition = new window.webkitSpeechRecognition();
    recognition.lang = getUILanguage();

    ref.current.recognition = recognition;
    recognition.continuous = true;
    recognition.interimResults = true;

    let autoStopTimer;
    const autoStop = (timeout) => {
      if (autoStopTimer) window.clearTimeout(autoStopTimer);

      autoStopTimer = setTimeout(() => {
        ref.current.recognition.stop();
      }, timeout);
    };

    recognition.onstart = () => {
      autoStop(10000);
      finalTranscript = '';
      setMessage('info_speak_now');

      setTimeout(() => {
        setMessage('info_listening');
      }, 1000);
    };

    recognition.onerror = (event) => {
      if (event.error === 'no-speech') {
        setMessage('info_no_speech');
        ref.current.ignoreOnend = true;
      }
      if (event.error === 'audio-capture') {
        setMessage('info_no_microphone');
        ref.current.ignoreOnend = true;
      }
      if (event.error === 'not-allowed') {
        if (event.timeStamp - ref.current.startTimestamp < 100) {
          setMessage('info_blocked');
        } else {
          setMessage('info_denied');
        }
        ref.current.ignoreOnend = true;
      }
    };

    recognition.onend = () => {
      setRecognizing(false);
      if (ref.current.ignoreOnend) return;

      if (!finalTranscript) {
        setMessage('info_no_recognized');
      }

      if (ref.current.text) {
        // handleSetText(finalTranscript);
        handleClose(ref.current.text);
      }
    };

    recognition.onsoundstart = () => {
      setIsSpeaking(true);
      autoStop(3000);
    };

    recognition.onsoundend = () => {
      setIsSpeaking(false);
    };

    recognition.onresult = (event) => {
      if (typeof event.results === 'undefined') {
        recognition.onend = null;
        recognition.stop();
        setMessage('info_upgrade');
        return;
      }

      let interimTranscript = '';
      for (let i = event.resultIndex; i < event.results.length; ++i) {
        if (event.results[i].isFinal) {
          finalTranscript += event.results[i][0].transcript;
        } else {
          interimTranscript += event.results[i][0].transcript;
        }
      }

      handleSetText(finalTranscript || interimTranscript);

      let timeout = 3000;
      if (interimTranscript) timeout = 2000;
      if (finalTranscript) timeout = 1000;
      autoStop(timeout);
    };

    recognition.start();
  }, []);

  useEffect(() => {
    const listener = (event) => {
      if (event.key === 'Escape') handleClose();
    };
    document.addEventListener('keydown', listener);
    return () => {
      document.removeEventListener('keydown', listener);
    };
  }, []);

  return (
    <div className={styles.voiceSearchContainer}>
      <button className={styles.close} onClick={() => handleClose()}>
        <img src="img/ic-cancel-white.svg" alt="" />
      </button>

      <div className={styles.voiceContent}>
        <div>
          <div>{text}</div>
          {message && !text && (
            <div>
              <span dangerouslySetInnerHTML={{ __html: MESSAGES[message] }} />
              {message === 'info_no_recognized' && (
                <a className={styles.voiceTryAgain} onClick={tryAgain}>
                  {MESSAGES.info_try_again}
                </a>
              )}
            </div>
          )}
        </div>

        <div>
          <button
            type="button"
            className={`${styles.microphoneButton} ${
              isRecognizing ? styles.isRecognizing : ''
            } ${isSpeaking ? styles.isSpeaking : ''}`}
          >
            <svg
              className="MuiSvgIconRoot"
              focusable="false"
              viewBox="0 0 24 24"
              aria-hidden="true"
            >
              <path d="M12 14c1.66 0 2.99-1.34 2.99-3L15 5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3zm5.3-3c0 3-2.54 5.1-5.3 5.1S6.7 14 6.7 11H5c0 3.41 2.72 6.23 6 6.72V21h2v-3.28c3.28-.48 6-3.3 6-6.72h-1.7z" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
};

export default VoiceSearch;
